1	#!/usr/bin/env bun
2	/**
3	 * dispatch_pr_validation.ts — hand a pull request to validation, from a workflow step.
4	 *
5	 * ## Why a person's command goes through validation rather than straight to the agent
6	 *
7	 * A person commenting `/<agent>` on a pull request is asking for a run, and the run
8	 * they are asking for is a judgement about a commit. Starting it immediately means
9	 * it reads a CI result that does not exist yet -- so it either waits with nothing
10	 * able to wake it, or reviews a commit whose checks have not run. Validation is the
11	 * thing that runs CI and waits, and it already dispatches whoever the result calls
12	 * for.
13	 *
14	 * So every agent start on a pull request goes through it, whoever asked: an agent's
15	 * handoff, a person's comment, and the re-validation after a push. One path, one
16	 * place that knows how to wait.
17	 *
18	 * ## What `asked-by-person` changes
19	 *
20	 * Who a FAILED check goes back to. An agent that broke its own pull request fixes
21	 * it; a person who asked for a run is owed the answer themselves, and handing their
22	 * request to an agent would be the machinery deciding on their behalf. See
23	 * `ValidationInput.askedByPerson`.
24	 *
25	 * Usage:
26	 *   dispatch_pr_validation.ts --repo OWNER/REPO --number N --branch B [--asked-by-person]
27	 *     [--ask ID]
28	 */
29	import { parseArgs } from "node:util";
30	import { dispatchPrValidation } from "../../adapters/actions/dispatch-targets.ts";
31	import { isTrue } from "./lib/flags.ts";
32	import { defineScript } from "./lib/script-ref.ts";
33	
34	export interface DispatchPrValidationArgs {
35	  repo: string;
36	  number: string | number;
37	  branch: string;
38	  "asked-by-person"?: string;
39	  /**
40	   * The ask comment id the run validation dispatches should claim (#285): the
41	   * person's command for the manual-comment path, the `waiting` ending for
42	   * `create_pr`'s, the pushing run's own claim for the re-validation after a push.
43	   * The answers-request check verifies the wait against THIS id, and the runner
44	   * writes its `atomaton:took` from it.
45	   */
46	  ask?: string;
47	}
48	
49	export const ref = defineScript<DispatchPrValidationArgs>(import.meta.url);
50	
51	function main(): void {
52	  const { values } = parseArgs({
53	    args: Bun.argv.slice(2),
54	    options: {
55	      repo: { type: "string" },
56	      number: { type: "string" },
57	      branch: { type: "string" },
58	      "asked-by-person": { type: "string" },
59	      ask: { type: "string" },
60	    },
61	  });
62	
63	  const repo = values.repo ?? "";
64	  const number = values.number ?? "";
65	  const branch = values.branch ?? "";
66	  if (!repo || !number || !branch) {
67	    console.error("usage: dispatch_pr_validation.ts --repo OWNER/REPO --number N --branch B");
68	    process.exit(2);
69	  }
70	
71	  // `dispatchPrValidation` reads the agent names from the pull request itself, so
72	  // there is nothing to pass but the target. `asked-by-person` travels as a
73	  // workflow input because it is a fact about THIS request rather than about the
74	  // pull request -- the same pull request can be validated by an agent's push and
75	  // by a person's comment, and the two route a failure differently.
76	  const dispatched = dispatchPrValidation(repo, Number(number), branch, {
77	    askedByPerson: isTrue(values["asked-by-person"]),
78	    ask: (values.ask ?? "").trim() || undefined,
79	  });
80	  if (!dispatched) {
81	    // Fatal, unlike most dispatches. The person asked for a run and nothing was
82	    // started; saying so in the log is the only place left, because nothing on this
83	    // workflow's path posts before validation -- the "CI is running" comment a
84	    // person may eventually see comes from validation itself, which never runs when
85	    // its own dispatch failed. (An earlier version of this comment blamed the
86	    // waiting comment this step used to post; that step is gone -- #271 moved the
87	    // comment into validation.)
88	    console.error(`::error::could not dispatch validation for PR #${number}; no agent will run`);
89	    process.exit(1);
90	  }
91	  console.error(`dispatched validation for PR #${number}`);
92	}
93	
94	if (import.meta.main) main();

