1	/**
2	 * Pins the parked turn's wiring in the generated runner (#208).
3	 *
4	 * The label a parked run keeps is decided by `decide_turn_ending` from a `parked`
5	 * signal the runner reads out of its own ops log — the `dispatch-elsewhere` entry a
6	 * child-starting tool writes. If either half of that wiring disappears from the
7	 * generated workflow, a parked run's label is removed at job end and the node looks
8	 * free while its subtree is still working — the exact state 判断1-A exists to make
9	 * visible.
10	 */
11	import { describe, expect, test } from "bun:test";
12	import { readFileSync } from "node:fs";
13	
14	type Step = { name?: string; run?: string };
