17	describe("the parked turn's wiring (#208)", () => {
18	  const workflow = Bun.YAML.parse(
19	    readFileSync("dist/.github/workflows/atomaton-runner.yml", "utf8"),
20	  ) as WorkflowDocument;
21	  const steps = Object.values(workflow.jobs ?? {}).flatMap((job) => job.steps ?? []);
22	
23	  test("the agent step publishes the parked signal from its own ops log", () => {
24	    const read = steps.find((s) => (s.run ?? "").includes("parked=${PARKED}"));
